export function translateEnglishSource(source) {
  let translated = source;
  for (const [japanese, english] of [...replacements].sort((a, b) => b[0].length - a[0].length)) {
    translated = translated.split(japanese).join(english);
  }
  return translated;
}

export function finalizeEnglishHtml(source) {
  return translateEnglishSource(source)
    .replace('<html lang="ja">', '<html lang="en">')
    .replace(
      '<link rel="canonical" href="https://m-kondo26.github.io/tools/sspz-simulator/">',
      '<link rel="canonical" href="https://m-kondo26.github.io/tools/sspz-simulator/index-en.html">',
    )
    .replace(
      '<meta property="og:url" content="https://m-kondo26.github.io/tools/sspz-simulator/">',
      '<meta property="og:url" content="https://m-kondo26.github.io/tools/sspz-simulator/index-en.html">',
    )
    .replace(
      '<a class="language-link" href="index-en.html" data-language-target="index-en.html" lang="en">English</a>',
      '<a class="language-link" href="index.html" data-language-target="index.html" lang="ja">Japanese</a>',
    )
    .replace('href="https://m-kondo26.github.io/ja/#contact"', 'href="https://m-kondo26.github.io/#contact"')
    .replace(/src="worker-source\.js(\?[^\"]*)?"/g, 'src="worker-source-en.js$1"')
    .replace(/src="app-bundle\.js(\?[^\"]*)?"/g, 'src="app-bundle-en.js$1"');
}
